import math, itertools, random, heapq, sys, subprocess, hashlib
from array import array
from pathlib import Path

def assignment(text):
    v = list(map(int, text.split()))
    n = v[0]
    a = v[1:n + 1]
    b = v[n + 1:]
    dp = [-100] * (1 << n)
    dp[0] = 0
    for mask in range(1 << n):
        i = bin(mask).count('1')
        if i == n:
            continue
        for j in range(n):
            if not mask >> j & 1:
                dp[mask | 1 << j] = max(dp[mask | 1 << j], dp[mask] + (b[j] > a[i]) - (b[j] < a[i]))
    return str(dp[-1])
import sys
sys.stdout.write(assignment(sys.stdin.read()) + '\n')

