def gifts(text):
    v = list(map(int, text.split()))
    out = []
    for (m, n) in zip(v[1::2], v[2::2]):
        dp = [0] * (m + 1)
        dp[0] = 1
        for k in range(1, min(m, n) + 1):
            for j in range(k, m + 1):
                dp[j] += dp[j - k]
        out.append(str(dp[m]))
    return '\n'.join(out)
