using namespace std;const long long MOD=1000000007;unordered_map<string,long long>memo;
long long solve(vector<int>a){int n=a.size();if(n==1)return a[0]==0;sort(a.begin(),a.end());int sum=accumulate(a.begin(),a.end(),0);if(a.front()<0||a.back()>3*(n-1)||sum<n*(n-1)||sum>3*n*(n-1)/2)return 0;string key;for(int x:a)key+=char(x+1);if(memo.count(key))return memo[key];int target=a[0];vector<int>b(a.begin()+1,a.end());long long ans=0;function<void(int,int)>dfs=[&](int p,int need){if(need<0||need>3*(n-1-p))return;if(p==n-1){if(!need)ans=(ans+solve(b))%MOD;return;}int orig=b[p];for(auto [ours,theirs]:vector<pair<int,int>>{{0,3},{1,1},{3,0}}){int left=orig-theirs;if(left<0||left>3*(n-2))continue;b[p]=left;dfs(p+1,need-ours);}b[p]=orig;};dfs(0,target);return memo[key]=ans;}
