def car(text):
    t = text.split()
    (h, w) = map(int, t[:2])
    board = t[2:2 + h]
    directions = t[3 + h:]
    old = [[c == '*' for c in row] for row in board]
    for direction in directions:
        new = [[False] * w for r in range(h)]
        if direction in ('NORTH', 'SOUTH'):
            order = range(h - 1, -1, -1) if direction == 'NORTH' else range(h)
            for c in range(w):
                seen = False
                for r in order:
                    if board[r][c] == 'X':
                        seen = False
                    else:
                        new[r][c] = seen
                        seen = seen or old[r][c]
        else:
            order = range(w - 1, -1, -1) if direction == 'WEST' else range(w)
            for r in range(h):
                seen = False
                for c in order:
                    if board[r][c] == 'X':
                        seen = False
                    else:
                        new[r][c] = seen
                        seen = seen or old[r][c]
        old = new
    return '\n'.join((''.join(('X' if board[r][c] == 'X' else '*' if old[r][c] else '.' for c in range(w))) for r in range(h)))
