import re, itertools, random, json
from collections import Counter

def switch_distribution(effects, k):
    distribution = {(0,) * k: 1}
    for effect in effects:
        nxt = Counter(distribution)
        for (state, freq) in distribution.items():
            nxt[tuple(((a + b) % 3 for (a, b) in zip(state, effect)))] += freq
        distribution = dict(nxt)
    return distribution

def switch_certificate(text, output):
    try:
        t = text.split()
        (n, k, count) = map(int, t[:3])
        wanted = {tuple(('AEI'.index(c) for c in t[i])): int(t[i + 1]) for i in range(3, len(t), 2)}
        lines = output.split()
        if len(lines) != n or any((len(line) != k or set(line) - set('+-0') for line in lines)):
            return False
        effects = [tuple(({'+': 1, '-': 2, '0': 0}[c] for c in row)) for row in lines]
        return switch_distribution(effects, k) == wanted
    except (ValueError, KeyError, IndexError, TypeError):
        return False
import sys
