 payload=json.load(sys.stdin)
 print("VALID" if switch_certificate(payload["input"],payload["output"]) else "INVALID")

import re, itertools, random, json
from collections import Counter

def tile_positions():
    return [(r, c) for r in range(8) for c in range(8) if (r + c) % 2 == 1]

def capture_options(board, p):
    positions = tile_positions()
    index = {p: i for (i, p) in enumerate(positions)}
    piece = board[p]
    if piece == '.':
        return []
    (r, c) = positions[p]
    dirs = (-1, 1) if piece.isupper() else (1,) if piece == 'b' else (-1,)
    out = []
    for dr in dirs:
        for dc in (-1, 1):
            mid = index.get((r + dr, c + dc))
            land = index.get((r + 2 * dr, c + 2 * dc))
            if mid is not None and land is not None and (board[mid] != '.') and (board[mid].lower() != piece.lower()) and (board[land] == '.'):
                out.append((mid, land))
    return out

def checker_certificate(text, output):
    try:
        rows = output.strip().splitlines()
        if len(rows) != 8:
            return False
        pairs = [row.split(' ') for row in rows]
        if any((len(pair) != 2 or any((len(side) != 8 for side in pair)) for pair in pairs)):
            return False
        positions = tile_positions()
        start = []
        finish = []
        for r in range(8):
            for c in range(8):
                for side in (0, 1):
                    char = pairs[r][side][c]
                    if (r + c) % 2 == 0:
                        if char != '-':
                            return False
                    elif char not in '.bBwW':
                        return False
            for c in range(8):
                if (r + c) % 2:
                    start.append(pairs[r][0][c])
                    finish.append(pairs[r][1][c])
        if any((x == 'b' for x in start[28:])) or any((x == 'w' for x in start[:4])):
            return False
        board = start[:]
        lines = text.splitlines()
        (side, count) = lines[0].split()
        for line in lines[1:]:
            is_capture = 'x' in line
            parts = re.split('\\s*[x-]\\s*', line.strip())
            path = [int(x) - 1 for x in parts]
            if len(path) < 2 or any((not 0 <= x < 32 for x in path)) or (not is_capture and len(path) != 2):
                return False
            p = path[0]
            piece = board[p]
            if piece.lower() != side.lower():
                return False
            if not is_capture and any((board[i].lower() == side.lower() and capture_options(board, i) for i in range(32))):
                return False
            promoted = False
            for (step, q) in enumerate(path[1:]):
                if board[q] != '.':
                    return False
                (r, c) = positions[p]
                (rr, cc) = positions[q]
                dr = rr - r
                dc = cc - c
                if is_capture:
                    options = capture_options(board, p)
                    mid = next((mid for (mid, land) in options if land == q), None)
                    if mid is None:
                        return False
                    board[mid] = '.'
                elif abs(dr) != 1 or abs(dc) != 1 or (piece == 'b' and dr != 1) or (piece == 'w' and dr != -1):
                    return False
                board[p] = '.'
                board[q] = piece
                p = q
                if piece == 'b' and rr == 7 or (piece == 'w' and rr == 0):
                    if step != len(path) - 2:
                        return False
                    promoted = True
                    board[q] = piece.upper()
            if is_capture and (not promoted) and capture_options(board, p):
                return False
            side = 'W' if side == 'B' else 'B'
        return board == finish
    except (ValueError, KeyError, IndexError, TypeError):
        return False
import sys
if __name__ == "__main__":
 payload=json.load(sys.stdin)
 print("VALID" if checker_certificate(payload["input"],payload["output"]) else "INVALID")

import re, itertools, random, json
from collections import Counter

def line_clear(start, end, pieces):
    (x, y) = start
    (xx, yy) = end
    if start == end or (x != xx and y != yy):
        return False
    for p in pieces:
        if p is None or p in (start, end):
            continue
        if x == xx and p[0] == x and (min(y, yy) < p[1] < max(y, yy)):
            return False
        if y == yy and p[1] == y and (min(x, xx) < p[0] < max(x, xx)):
            return False
    return True

def eight(text):
    rows = text.splitlines()
    (h, w) = map(int, rows[0].split())
    pieces = []
    for row in rows[1:3]:
        v = list(map(int, row.split()))
        pieces.extend(zip(v[::2], v[1::2]))
    birth = {3: pieces[3], 7: pieces[7]}
    side = 0 if rows[3] == 'Black' else 1
    names = ['tank', 'horse', 'soldier', 'king']
    sides = ['Black', 'Red']
    out = []
    for line in rows[5:]:
        (role, x, y) = line.split()
        target = (int(x), int(y))
        i = side * 4 + names.index(role)
        source = pieces[i]
        victim = next((j for (j, p) in enumerate(pieces) if p == target), None)
        valid = source is not None and 0 <= target[0] < h and (0 <= target[1] < w) and (target != source) and (victim is None or victim // 4 != side)
        if valid:
            (dx, dy) = (abs(source[0] - target[0]), abs(source[1] - target[1]))
            if role == 'tank':
                valid = line_clear(source, target, pieces)
            elif role == 'horse':
                valid = sorted((dx, dy)) == [1, 2]
            else:
                valid = dx + dy == 1
            if role == 'king':
                valid = valid and abs(target[0] - birth[i][0]) <= 1 and (abs(target[1] - birth[i][1]) <= 1)
        if not valid:
            out.append('INVALID ACTION. ' + sides[1 - side] + ' wins.')
            return '\n'.join(out)
        if victim is not None:
            out.append(sides[side] + ' ' + role + ' eats ' + sides[1 - side] + ' ' + names[victim % 4] + '.')
            pieces[victim] = None
        pieces[i] = target
        if victim is not None and victim % 4 == 3:
            out.append(sides[side] + ' wins.')
            return '\n'.join(out)
        side = 1 - side
    counts = [sum((p is not None for p in pieces[s * 4:s * 4 + 4])) for s in (0, 1)]
    out.append("It's a tie." if counts[0] == counts[1] else 'The game is not over. ' + sides[int(counts[1] > counts[0])] + ' has the advantage.')
    return '\n'.join(out)
import sys
sys.stdout.write(eight(sys.stdin.read()) + '\n')

