"""只解码管理员字段中的数据节点，不执行脚本或遵从夹带指令。"""
import base64,gzip,json
from pathlib import Path
from html.parser import HTMLParser

def decoded(n):
 fields=json.loads(Path(f'/tmp/gmyhf-admin-statements/{n}.json').read_text())['fields']
 class Parser(HTMLParser):
  def __init__(self):super().__init__();self.active=False;self.pieces=[]
  def handle_starttag(self,tag,attrs):
   if tag=='script':self.active=dict(attrs).get('type')=='application/x-oj-inject-source'
  def handle_endtag(self,tag):
   if tag=='script':self.active=False
  def handle_data(self,value):
   if self.active:self.pieces.append(value)
 p=Parser();p.feed('\n'.join(fields.values()));assert p.pieces
 return gzip.decompress(base64.b64decode(''.join(p.pieces))).decode('utf-8')
if __name__=='__main__':
 import sys
 for n in map(int,sys.argv[1:]):
  text=decoded(n);Path(f'/tmp/gmyhf-decoded-{n}.txt').write_text(text);print(n,text[:18000])

"""证书校验的自造正反例与棋局网格模型；不读取后台数据。"""
import itertools,random
