def render(a,b):
 rows=[]
 for r in range(8):
  sides=[]
  for board in (a,b):sides.append(''.join('-' if (r+c)%2==0 else board[r*4+c//2] for c in range(8)))
  rows.append(' '.join(sides))
 return '\n'.join(rows)
def checker_cases():
 positions=[(r,c) for r in range(8) for c in range(8) if (r+c)%2];index={p:i for i,p in enumerate(positions)};cases=[]
 for i,(r,c) in enumerate(positions):
  for piece in 'bBwW':
   if (piece=='b' and r==7) or(piece=='w' and r==0):continue
   dirs=(-1,1) if piece.isupper() else (1,) if piece=='b' else (-1,)
   for dr in dirs:
    for dc in (-1,1):
     side=piece.upper()
     for jump in (False,True):
      j=index.get((r+(2 if jump else 1)*dr,c+(2 if jump else 1)*dc))
      if j is None:continue
      a=['.']*32;b=['.']*32;a[i]=piece;b[j]=piece.upper() if (piece=='b' and positions[j][0]==7) or(piece=='w' and positions[j][0]==0) else piece
      if jump:a[index[(r+dr,c+dc)]]='W' if side=='B' else 'B'
      given=f'{side} 1\n{i+1}'+('x' if jump else '-')+str(j+1);cases.append((given,render(a,b),True))
      # 终盘凭空多一个棋子。
      bad=b[:];q=next(x for x in range(32) if bad[x]=='.');bad[q]='B';cases.append((given,render(a,bad),False))
 # 全局存在别的可吃时不能走普通步。
 a=['.']*32;a[8]='B';a[13]='W';a[0]='B';b=a[:];b[0]='.';b[4]='B';cases.append(('B 1\n1-5',render(a,b),False))
 # 王可连吃：9x18之后仍能跳到27，提前停不合法。
 a=['.']*32;a[8]='B';a[13]='W';a[22]='W';b=a[:];b[8]='.';b[13]='.';b[17]='B';cases.append(('B 1\n9x18',render(a,b),False))
 b[17]='.';b[22]='.';b[26]='B';cases.append(('B 1\n9x18x27',render(a,b),True))
 # 普通b只可向下；初始b不能已在升级边。
 a=['.']*32;a[13]='b';b=a[:];b[13]='.';b[8]='b';cases.append(('B 1\n14-9',render(a,b),False))
 a=['.']*32;a[28]='b';b=a[:];b[28]='.';b[24]='b';cases.append(('B 1\n29-25',render(a,b),False))
 # 抵达升级边就结束；继续用王权限连跳仍不合法。
 a=['.']*32;a[20]='b';a[24]='W';a[25]='W';b=a[:];b[20]='.';b[24]='.';b[28]='B';cases.append(('B 1\n21x30',render(a,b),False)) # 正确落点不是30，独立几何拒绝。
 # 升级立即停止，即使升级后的王还有向后的可吃路径。
 a=['.']*32;a[20]='b';a[24]='W';a[25]='W';b=a[:];b[20]='.';b[24]='.';b[29]='B';cases.append(('B 1\n21x30',render(a,b),True))
 b[29]='.';b[25]='.';b[22]='B';cases.append(('B 1\n21x30x23',render(a,b),False))
 # 普通移到末行应升级，未升级终盘错误。
 a=['.']*32;a[24]='b';b=['.']*32;b[28]='b';cases.append(('B 1\n25-29',render(a,b),False));b[28]='B';cases.append(('B 1\n25-29',render(a,b),True))
