def game_reference(text):
 rows=text.splitlines();h,w=map(int,rows[0].split());names=['tank','horse','soldier','king'];labels=['Black','Red'];grid={};birth={}
 for side in range(2):
  values=list(map(int,rows[side+1].split()))
  for i in range(4):p=tuple(values[2*i:2*i+2]);grid[p]=(side,names[i]);birth[side,names[i]]=p
 side=labels.index(rows[3]);out=[]
 for row in rows[5:]:
  role,xx,yy=row.split();target=int(xx),int(yy);source=next((p for p,identity in grid.items() if identity==(side,role)),None);possible=set()
  if source is not None:
   x,y=source
   if role=='tank':
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     r,c=x+dr,y+dc
     while 0<=r<h and 0<=c<w:
      if (r,c) not in grid:possible.add((r,c))
      else:
       if grid[r,c][0]!=side:possible.add((r,c))
       break
      r+=dr;c+=dc
   else:
    deltas=[(a,b) for a in range(-2,3) for b in range(-2,3) if (abs(a)*abs(b)==2 if role=='horse' else abs(a)+abs(b)==1)]
    for dr,dc in deltas:
     p=x+dr,y+dc
     if not(0<=p[0]<h and 0<=p[1]<w) or(p in grid and grid[p][0]==side):continue
     if role=='king' and max(abs(p[0]-birth[side,role][0]),abs(p[1]-birth[side,role][1]))>1:continue
     possible.add(p)
  if target not in possible:return '\n'.join(out+['INVALID ACTION. '+labels[1-side]+' wins.'])
  victim=grid.get(target)
  if victim:out.append(labels[side]+' '+role+' eats '+labels[1-side]+' '+victim[1]+'.')
  del grid[source];grid[target]=(side,role)
  if victim and victim[1]=='king':return '\n'.join(out+[labels[side]+' wins.'])
  side=1-side
 counts=Counter(s for s,role in grid.values());out.append("It's a tie." if counts[0]==counts[1] else 'The game is not over. '+labels[int(counts[1]>counts[0])]+' has the advantage.');return '\n'.join(out)

