   for bits in itertools.product((0,1),repeat=n):freq[tuple(sum(effects[j][i]*bits[j] for j in range(n))%3 for i in range(k))]+=1
   expected=m.switch_distribution(effects,k);assert expected==dict(freq)
   text=f'{n} {k} {len(freq)}\n'+'\n'.join(''.join('AEI'[x] for x in state)+' '+str(f) for state,f in freq.items());output='\n'.join(''.join('0+-'[x] for x in effect) for effect in effects);assert m.switch_certificate(text,output);assert not m.switch_certificate(text,output+'\n'+'0'*k);assert not m.switch_certificate(text,'?'+output[1:]);counts[30548]+=3
