   h=w=5;p=rng.sample([(r,c) for r in range(h) for c in range(w)],8);side=rng.choice(('Black','Red'));n=rng.randrange(0,12);moves=[]
   for i in range(n):moves.append(rng.choice(('tank','horse','soldier','king'))+' '+str(rng.randrange(-1,6))+' '+str(rng.randrange(-1,6)))
   text='5 5\n'+' '.join(str(x) for cell in p[:4] for x in cell)+'\n'+' '.join(str(x) for cell in p[4:] for x in cell)+'\n'+side+'\n'+str(n)+'\n'+'\n'.join(moves);assert m.eight(text)==game_reference(text);counts[31186]+=1
